INSERT INTO `creature_text` (`entry`,`groupid`,`id`,`text`,`type`,`language`,`probability`,`emote`,`duration`,`sound`,`comment`) VALUES
(3887,0,0,'Leave this accursed place at once!',14,0,100.0,0,0,0,'Baron Silverlaine - Aggro'),
(3887,1,0,'This death is only a temporary respite from my curse.',14,0,100.0,0,0,0,'Baron Silverlaine - Death'),
(3887,2,0,'I hope your spirit finds solace.',14,0,100.0,0,0,0,'Baron Silverlaine - Slay 1'),
(3887,2,1,'May your soul rest in peace.',14,0,100.0,0,0,0,'Baron Silverlaine - Slay 2'),
(4278,0,0,'Intruders in the keep! To arms!',14,0,100.0,0,0,0,'Commander Springvale - Aggro'),
(4278,1,0,'Repel the intruders!',14,0,100.0,0,0,0,'Commander Springvale - Summon Adds'),
(4278,2,0,'The attackers weaken!',14,0,100.0,0,0,0,'Commander Springvale - Slay 1'),
(4278,2,1,'One step closer to victory!',14,0,100.0,0,0,0,'Commander Springvale - Slay 2'),
(4278,3,0,'Our vigilance is eternal...',14,0,100.0,0,0,0,'Commander Springvale - Death'),
(36272,0,0,'Great. We\'re not gutless, we\'re incompetent.',12,0,100.0,0,0,0,'SAY_FRYE_DEATH'),
(36296,0,0,'Did they bother to tell you who I am and why I am doing this?',12,0,100.0,6,0,0,'SAY_INTRO_0'),
(36296,1,0,'...or are they just using you like they do everybody else?',12,0,100.0,396,0,0,'SAY_INTRO_1'),
(36296,2,0,'But what does it matter.  It is time for this to end.',12,0,100.0,397,0,0,'SAY_INTRO_2'),
(36296,3,0,'Baxter! Get in here and help! NOW!',12,0,100.0,0,0,0,'SAY_CALL_BAXTER'),
(36296,4,0,'It is time, Frye!  Attack!',12,0,100.0,0,0,0,'SAY_CALL_FRYE'),
(36296,5,0,'...please don\'t think less of me.',12,0,100.0,0,0,0,'SAY_HUMMEL_DEATH'),
(36565,0,0,'It has been the greatest honor of my life to serve with you, Hummel.',12,0,100.0,0,0,0,'SAY_BAXTER_DEATH'),
(43679,0,0,'A nearby Gargoyle comes to life!',41,0,100.0,0,0,0,'DEBUG Announcer'),
(46962,0,0,'Tally ho! The hunt begins!',14,0,0.0,0,0,0,'SAY_AGGRO'),
(46962,1,0,'Tally ho! The hunt begins!',14,0,100.0,0,0,0,'Baron Ashbury'),
(46962,2,0,'This is just too easy...',14,0,100.0,0,0,0,'Baron Ashbury'),
(46962,3,0,'|TInterface\\Icons\\spell_holy_healingaura.blp:20|tBaron Ashbury begins to channel |cFFFF0000|Hspell:93468|h\'Stay of Execution\'|h|r !',41,0,100.0,0,0,0,'Baron Ashbury'),
(46962,4,0,'HA! Let\'s at least keep it interesting.',14,0,100.0,0,0,0,'Baron Ashbury'),
(46962,5,0,'I grow tired of this hunt... Time to die!',14,0,100.0,0,0,0,'Baron Ashbury'),
(46962,5,1,'There was no sport in that kill.',14,0,0.0,0,0,0,'SAY_KILL 2'),
(46962,6,0,'Killed by lowly commoners, how droll...',14,0,100.0,0,0,0,'Baron Ashbury'),
(46963,0,0,'Even here I find myself beset by fools!',14,0,100.0,0,0,0,'Lord Walden - Aggro'),
(46963,1,0,'This childish effort ends now!',14,0,100.0,0,0,0,'Lord Walden - Slay 1'),
(46963,1,1,'You shall annoy me no longer!',14,0,100.0,0,0,0,'Lord Walden - Slay 2'),
(46963,2,0,'My new life was just beginning...',14,0,100.0,0,0,0,'Lord Walden - Death'),
(46963,2,1,'You shall annoy me no longer!',14,0,0.0,0,0,0,'SAY_KILL 2'),
(46963,3,0,'This library should prove to be useful to my own research.',12,0,100.0,0,0,0,'Lord Walden'),
(46963,3,1,'I must give Arugal some credit, his lines of research were quite novel.',12,0,100.0,0,0,0,'Lord Walden'),
(46963,3,2,'Missing pages, broken equipment, tainted samples! How does someone work in these conditions!',12,0,100.0,0,0,0,'Lord Walden'),
(46963,3,3,'These notes are horribly organized. I can\'t tell if Arugal was brilliant or simply an imbecile.',12,0,100.0,0,0,0,'Lord Walden'),
(46964,0,0,'Ivar\'s pack failed horribly, so now he sends mercenaries. No matter, your journey ends in agony.',14,0,100.0,0,0,0,'Lord Godfrey - Aggro Alliance'),
(46964,1,0,'That bitch Sylvanas sent you too, did she? No matter, your journey ends in agony.',14,0,100.0,0,0,0,'Lord Godfrey - Aggro Horde'),
(46964,2,0,'Murder never gets old.',14,0,100.0,0,0,0,'Lord Godfrey - Aggro Horde'),
(46964,2,1,'This is the quality of assassin sent to kill me? Laughable.',14,0,100.0,0,0,0,'Lord Godfrey - Aggro Horde'),
(46964,3,0,'|TInterface\\Icons\\INV_FIREARM_2H_RIFLE_CATACLYSM_B_01.BLP:20|t%s begins to cast |cFFFF0000|Hspell:93520|h[Pistol Barrage]|h|r!',41,0,100.0,0,0,0,'Lord Godfrey Pistol Barrage'),
(46964,3,1,'This is the quality of assassin sent to kill me? Laughable.',14,0,0.0,0,0,0,'SAY_KILL2'),
(46964,4,0,'I thank you for the clean death. I would not have done the same...',14,0,100.0,0,0,0,'Lord Godfrey'),
(47293,0,0,'You\'re more skilled in combat than I thought.',12,0,100.0,1,0,0,'Deathstalker Commander Belmont to Player'),
(47293,1,0,'Very well then. Let\'s get the courtyard door open so we can continue our mission!',12,0,100.0,1,0,0,'Deathstalker Commander Belmont to Player'),
(47293,2,0,'This lock should be easy enough to pick.',12,0,100.0,1,0,0,'Deathstalker Commander Belmont to Player'),
(47293,3,0,'There we go!',12,0,100.0,0,0,0,'Deathstalker Commander Belmont to Player'),
(47293,4,0,'Excellent. Now, to plague this area and move on to-',12,0,100.0,396,0,0,'Deathstalker Commander Belmont to Player'),
(47293,5,0,'Cromush! What\'re you doing here? This is a covert operation!',12,0,100.0,5,0,0,'Deathstalker Commander Belmont to Player'),
(47293,6,0,'My apologies, Cromush, but I assure you there is no problem. We are using an extremely dilute plague.',12,0,100.0,396,0,0,'Deathstalker Commander Belmont to Player'),
(47293,7,0,'In fact, it really only serves to scare off the worgen from trying to follow us in here. It\'s completely harmless.',12,0,100.0,396,0,0,'Deathstalker Commander Belmont to Player'),
(47293,8,0,'The time has come, soldiers! Godfrey lies just ahead! Have no mercy! We fight-',12,0,100.0,396,0,0,'Deathstalker Commander Belmont to Player'),
(47293,9,0,'You\'d better hurry up if you want in on all the fun.',12,0,100.0,153,0,0,'Deathstalker Commander Belmont to Player'),
(47293,10,0,'Why is the door shut? What in Sylvanas\' name is going on here...',12,0,100.0,396,0,0,'Deathstalker Commander Belmont to Player'),
(47293,11,0,'Cromush! What happened?',12,0,100.0,396,0,0,'Deathstalker Commander Belmont to Player'),
(47293,12,0,'You\'ll pay for this Godfrey!',12,0,100.0,397,0,0,'Deathstalker Commander Belmont to Player'),
(47293,13,0,'You\'d better hurry up if you want in on all the fun.',12,0,100.0,1,0,0,'Walden event'),
(47293,14,0,'Why is the door shut? What in Sylvanas\' name is going on here...',12,0,100.0,1,0,0,'Pre Godfrey event'),
(47293,15,0,'Cromush! What happened?',12,0,100.0,1,0,0,'Pre Godfrey event'),
(47293,16,0,'You\'ll pay for this Godfrey!',12,0,100.0,1,0,0,'Pre Godfrey event'),
(47293,17,0,'Heroes, you must kill Godfrey! I\'ll make sure nothing interferes!',12,0,100.0,1,0,0,'Pre Godfrey event'),
(47294,0,0,'Unless I\'m mistaken, the Warchief explicity forbids using the full plague, no matter the circumstance.',12,0,100.0,396,0,0,'High Warlord Cromush to Player'),
(47294,1,0,'Then I\'m sure you won\'t mind if I accompany you on your mission.',12,0,100.0,396,0,0,'High Warlord Cromush to Player'),
(47294,2,0,'FOR THE HORDE!!!',14,0,100.0,71,0,0,'High Warlord Cromush to Player'),
(47294,3,0,'The coward...killed them...poisoned...me...',12,0,100.0,0,0,0,'High Warlord Cromush to Player'),
(47294,4,0,'FOR THE HORDE!!!',14,0,100.0,1,0,0,'Cromush Walden killed'),
(47294,5,0,'The coward...killed them...poisoned...me...',12,0,100.0,1,0,0,'Cromush poisoned'),
(47862,0,0,'Better to rot in this cell than live as a dishonorable traitor.',12,0,100.0,1,0,0,'Magistrate Henry Maleb'),
(48124,0,0,'The Rabid Mastiff slobbers all over the floor...',16,0,100.0,0,0,0,'Rabid Mastiff'),
(48124,0,1,'The dog stares blankly at the wall...',16,0,100.0,0,0,0,'Rabid Mastiff'),
(48124,0,2,'A Rabid Mastiff growls...',16,0,100.0,0,0,0,'Rabid Mastiff');
