INSERT INTO `creature_text` (`entry`,`groupid`,`id`,`text`,`type`,`language`,`probability`,`emote`,`duration`,`sound`,`comment`) VALUES
(47006,0,0,'Pathetic.',12,0,100.0,1,0,0,'Packleader Ivar Bloodfang to Player'),
(47006,1,0,'Keep moving forward. My men will dispose of this sorry bag of bones.',12,0,100.0,1,0,0,'Packleader Ivar Bloodfang to Player'),
(47006,2,0,'Control yourselves! We''re here for Godfrey''s head above all else. Relish in the spoils of war later!',12,0,100.0,5,0,0,'Packleader Ivar Bloodfang to Player'),
(47006,3,0,'We have to push forward if we''re to put an end to him. Follow me, I''ll open the courtyard so that you can spearhead our assault.',12,0,100.0,0,0,0,'Packleader Ivar Bloodfang to Player'),
(47006,4,0,'What a pathetic lock! Godfrey is going to have to try harder than this if he wants to defeat us.',12,0,100.0,0,0,0,'Packleader Ivar Bloodfang to Player'),
(47006,5,0,'The Bloodfang Berserkers begin to salivate heavily.',16,0,100.0,0,0,0,'Packleader Ivar Bloodfang to Player'),
(47006,6,0,'The Bloodfang come for you, worgen hunters!',14,0,100.0,15,0,0,'Packleader Ivar Bloodfang to Player'),
(47006,7,0,'I''ve picked up Walden''s foul scent. Fill the air with his blood!',12,0,100.0,1,0,0,'Packleader Ivar Bloodfang to Player'),
(47006,8,0,'Your time has finally come, Godfrey!',14,0,100.0,53,0,0,'Packleader Ivar Bloodfang to Player'),
(47006,9,0,'Attack, my brothers! Make him feel the fury of the pack!',14,0,100.0,25,0,0,'Packleader Ivar Bloodfang to Player'),
(47006,10,0,'You''d best hurry if you want any of the spoils.',12,0,100.0,0,0,0,'Packleader Ivar Bloodfang to Player'),
(47006,11,0,'I don''t know why the door is closed, heroes. My pack should have already taken care of Godfrey by now...',12,0,100.0,1,0,0,'Packleader Ivar Bloodfang to Player'),
(47006,12,0,'We will stand idle no longer! The time to act is now!',12,0,100.0,1,0,0,'Packleader Ivar Bloodfang to Player'),
(47006,13,0,'I''ll make sure nothing interferes. Go now heroes! Kill Godfrey!',12,0,100.0,0,0,0,'Packleader Ivar Bloodfang to Player'),
(47006,14,0,'Crowley is a disgrace to our kind for giving in to the Forsaken. My pack will show them the true face of the worgen and the relentless fury that comes with our presence!',12,0,100.0,5,0,0,'Packleader Ivar Bloodfang'),
(47027,0,0,'Bones?',12,0,100.0,1,0,0,'Bloodfang Berserker'),
(47027,1,0,'Commander Springvale is down that hall, heroes.',12,0,100.0,397,0,0,'Bloodfang Berserker');
